  dialog: { do: ["Ask one question.", 'Make the primary button name the action ("Delete project").'], dont: ["Do not open a dialog from a dialog.", "Do not use for non-blocking messages; use Toast."] },
  toast: { do: ["Confirm what just happened in a sentence.", "Use duration 0 only when an action is required."], dont: ["Do not show more than three toasts at once.", "Do not use for errors that need a decision; use Dialog or Alert."] },
  avatar: { do: ["Always provide a name for initials and alt text."], dont: ["Do not use for logos."] },
  "radio-group": { do: ["Use for two to five exclusive options.", "Preselect the safest option."], dont: ["Do not use for long lists; use Select."] },
